  const prevYearButtonDisabled = yearDisabledBefore(
    this.state.date,
    this.props,
  );

  const nextYearButtonDisabled = yearDisabledAfter(
    this.state.date,
    this.props,
  );

  return (
    <div
      className="react-datepicker__header react-datepicker__header--custom"
      onFocus={this.props.onDropdownFocus}
    >
      {this.props.renderCustomHeader?.({
        ...this.state,
        ...(showYearPicker && { visibleYearsRange }),
        customHeaderCount: i,
        monthDate,
        changeMonth: this.changeMonth,
        changeYear: this.changeYear,
        decreaseMonth: this.decreaseMonth,
        increaseMonth: this.increaseMonth,
        decreaseYear: this.decreaseYear,
        increaseYear: this.increaseYear,
        prevMonthButtonDisabled,
        nextMonthButtonDisabled,
        prevYearButtonDisabled,
        nextYearButtonDisabled,
      })}
    </div>
  );
};

renderYearHeader = ({
  monthDate,
}: {
  monthDate: Date;
}): React.ReactElement => {
  const {
    showYearPicker,
    yearItemNumber = Calendar.defaultProps.yearItemNumber,
  } = this.props;
  const { startPeriod, endPeriod } = getYearsPeriod(
    monthDate,
    yearItemNumber,
  );
  return (
    <div className="react-datepicker__header react-datepicker-year-header">
      {showYearPicker ? `${startPeriod} - ${endPeriod}` : getYear(monthDate)}
    </div>
  );
};

renderHeader = ({
  monthDate,
  i = 0,
}: {
  monthDate: Date;
  i?: number;
}): React.ReactElement | null => {
  const headerArgs = { monthDate, i };
  switch (true) {
    case this.props.renderCustomHeader !== undefined:
      return this.renderCustomHeader(headerArgs);
    case this.props.showMonthYearPicker ||
      this.props.showQuarterYearPicker ||
      this.props.showYearPicker:
      return this.renderYearHeader(headerArgs);
    default:
      return this.renderDefaultHeader(headerArgs);
  }
};

renderMonths = (): React.ReactElement[] | undefined => {
  if (this.props.showTimeSelectOnly || this.props.showYearPicker) {
    return;
  }

  const monthList: React.ReactElement[] = [];
  const monthsShown =
    this.props.monthsShown ?? Calendar.defaultProps.monthsShown;
  const monthsToSubtract = this.props.showPreviousMonths
    ? monthsShown - 1
    : 0;
  const fromMonthDate =
    this.props.showMonthYearPicker || this.props.showQuarterYearPicker
      ? addYears(this.state.date, monthsToSubtract)
      : subMonths(this.state.date, monthsToSubtract);
  const monthSelectedIn = this.props.monthSelectedIn ?? monthsToSubtract;
  for (let i = 0; i < monthsShown; ++i) {
    const monthsToAdd = i - monthSelectedIn + monthsToSubtract;
    const monthDate =
      this.props.showMonthYearPicker || this.props.showQuarterYearPicker
        ? addYears(fromMonthDate, monthsToAdd)
        : addMonths(fromMonthDate, monthsToAdd);
    const monthKey = `month-${i}`;
    const monthShowsDuplicateDaysEnd = i < monthsShown - 1;
    const monthShowsDuplicateDaysStart = i > 0;
    monthList.push(
      <div
        key={monthKey}
        ref={(div) => {
          this.monthContainer = div ?? undefined;
        }}
        className="react-datepicker__month-container"
      >
        {this.renderHeader({ monthDate, i })}
        <Month
          {...Calendar.defaultProps}
          {...this.props}
          containerRef={this.containerRef}
          ariaLabelPrefix={this.props.monthAriaLabelPrefix}
          day={monthDate}
          onDayClick={this.handleDayClick}
          handleOnKeyDown={this.props.handleOnDayKeyDown}
          handleOnMonthKeyDown={this.props.handleOnKeyDown}
          onDayMouseEnter={this.handleDayMouseEnter}
          onMouseLeave={this.handleMonthMouseLeave}
          orderInDisplay={i}
          selectingDate={this.state.selectingDate}
          monthShowsDuplicateDaysEnd={monthShowsDuplicateDaysEnd}
          monthShowsDuplicateDaysStart={monthShowsDuplicateDaysStart}
          dayNamesHeader={this.renderDayNamesHeader(monthDate, i)}
        />
      </div>,
    );
  }
  return monthList;
};

renderYears = (): React.ReactElement | undefined => {
  if (this.props.showTimeSelectOnly) {
    return;
  }
  if (this.props.showYearPicker) {
    return (
      <div className="react-datepicker__year--container">
        {this.renderHeader({ monthDate: this.state.date })}
        <Year
          {...Calendar.defaultProps}
          {...this.props}
          selectingDate={this.state.selectingDate}
          date={this.state.date}
          onDayClick={this.handleDayClick}
          clearSelectingDate={this.clearSelectingDate}
          onYearMouseEnter={this.handleYearMouseEnter}
          onYearMouseLeave={this.handleYearMouseLeave}
        />
      </div>
    );
  }
  return;
};

renderTimeSection = (): React.ReactElement | undefined => {
  if (
    this.props.showTimeSelect &&
    (this.state.monthContainer || this.props.showTimeSelectOnly)
  ) {
    return (
      <Time

  showTwoColumnMonthYearPicker?: boolean,
) {
  if (showFourColumnMonthYearPicker) {
    return MONTH_COLUMNS_LAYOUT.FOUR_COLUMNS;
  }
  if (showTwoColumnMonthYearPicker) {
    return MONTH_COLUMNS_LAYOUT.TWO_COLUMNS;
  }
  return MONTH_COLUMNS_LAYOUT.THREE_COLUMNS;
}

interface WeekProps extends React.ComponentPropsWithoutRef<typeof Week> {}

interface MonthProps extends Omit<
  WeekProps,
  | "ariaLabelPrefix"
  | "chooseDayAriaLabelPrefix"
  | "day"
  | "disabledDayAriaLabelPrefix"
  | "month"
  | "onDayClick"
  | "onDayMouseEnter"
  | "preSelection"
  | "selected"
  | "showWeekNumber"
> {
  monthClassName?: (date: Date) => string;
  onDayClick?: (
    date: Date,
    event:
      | React.MouseEvent<HTMLDivElement>
      | React.KeyboardEvent<HTMLDivElement>,
    orderInDisplay?: number,
  ) => void;
  onDayMouseEnter?: (date: Date) => void;
  onMouseLeave?: VoidFunction;
  setPreSelection?: (date?: Date | null) => void;
  renderMonthContent?: (
    m: number,
    shortMonthText: string,
    fullMonthText: string,
    day: Date,
  ) => React.ReactNode;
  renderQuarterContent?: (q: number, shortQuarter: string) => React.ReactNode;
  handleOnMonthKeyDown?: (event: React.KeyboardEvent<HTMLDivElement>) => void;
  ariaLabelPrefix?: string;
  day: Date;
  startDate?: Date | null;
  endDate?: Date | null;
  orderInDisplay?: number;
  fixedHeight?: boolean;
  peekNextMonth?: boolean;
  preSelection?: Date | null;
  selected?: Date | null;
  showWeekNumbers?: WeekProps["showWeekNumber"];
  showMonthYearPicker?: boolean;
  showFullMonthYearPicker?: boolean;
  showTwoColumnMonthYearPicker?: boolean;
  showFourColumnMonthYearPicker?: boolean;
  showQuarterYearPicker?: boolean;
  weekAriaLabelPrefix?: WeekProps["ariaLabelPrefix"];
  chooseDayAriaLabelPrefix?: WeekProps["chooseDayAriaLabelPrefix"];
  disabledDayAriaLabelPrefix?: WeekProps["disabledDayAriaLabelPrefix"];
  dayNamesHeader?: React.ReactNode;
}

/**
 * `Month` is a React component that represents a month in a calendar.
 * It accepts a `MonthProps` object as props which provides various configurations and event handlers.
 *
 * @prop dayClassName - Function to determine the class name for a day.
 * @prop monthClassName - Function to determine the class name for a month.
 * @prop filterDate - Function to filter dates.
 * @prop formatWeekNumber - Function to format the week number.
 * @prop onDayClick - Function to handle day click events.
 * @prop onDayMouseEnter - Function to handle mouse enter events on a day.
 * @prop onMouseLeave - Function to handle mouse leave events.
 * @prop onWeekSelect - Function to handle week selection.
 * @prop setPreSelection - Function to set pre-selection.
 * @prop setOpen - Function to set open state.
 * @prop renderDayContents - Function to render day contents.
 * @prop renderMonthContent - Function to render month content.
 * @prop renderQuarterContent - Function to render quarter content.
 * @prop handleOnKeyDown - Function to handle key down events.
 * @prop handleOnMonthKeyDown - Function to handle key down events on a month.
 * @prop ariaLabelPrefix - Aria label prefix.
 * @prop chooseDayAriaLabelPrefix - Aria label prefix for choosing a day.
 * @prop disabledDayAriaLabelPrefix - Aria label prefix for disabled day.
 * @prop disabledKeyboardNavigation - Flag to disable keyboard navigation.
 * @prop day - The day.
 * @prop endDate - The end date.
 * @prop orderInDisplay - The order in display.
 * @prop excludeDates - Dates to exclude.
 * @prop excludeDateIntervals - Date intervals to exclude.
 * @prop fixedHeight - Flag to set fixed height.
 * @prop highlightDates - Dates to highlight.
 * @prop holidays - Holidays.
 * @prop includeDates - Dates to include.
 * @prop includeDateIntervals - Date intervals to include.
 * @prop inline - Flag to set inline.
 * @prop shouldFocusDayInline - Flag to set focus on day inline.
 * @prop locale - The locale.
 * @prop maxDate - The maximum date.
 * @prop minDate - The minimum date.
 * @prop usePointerEvent - Flag to use pointer event.
 * @prop peekNextMonth - Flag to peek next month.
 * @prop preSelection - The pre-selection.
 * @prop selected - The selected date.
 * @prop selectingDate - The selecting date.
 * @prop calendarStartDay - The calendar start day.
 * @prop selectsEnd - Flag to select end.
  };

  getClassNames = () => {
    const {
      selectingDate,
      selectsStart,
      selectsEnd,
      showMonthYearPicker,
      showQuarterYearPicker,
      showWeekPicker,
    } = this.props;

    return clsx(
      "react-datepicker__month",
      {
        "react-datepicker__month--selecting-range":
          selectingDate && (selectsStart || selectsEnd),
      },
      { "react-datepicker__monthPicker": showMonthYearPicker },
      { "react-datepicker__quarterPicker": showQuarterYearPicker },
      { "react-datepicker__weekPicker": showWeekPicker },
    );
  };

  render() {
    const {
      showMonthYearPicker,
      showQuarterYearPicker,
      day,
      ariaLabelPrefix = "Month ",
    } = this.props;

    const formattedAriaLabelPrefix = ariaLabelPrefix
      ? ariaLabelPrefix.trim() + " "
      : "";

    // Format aria-label, return empty string if date is invalid
    const formattedAriaLabel = isValid(day)
      ? `${formattedAriaLabelPrefix}${formatDate(day, "MMMM, yyyy", this.props.locale)}`
      : "";

    const shouldUseListboxRole = showMonthYearPicker || showQuarterYearPicker;

    if (shouldUseListboxRole) {
      return (
        <div
          className={this.getClassNames()}
          onMouseLeave={
            !this.props.usePointerEvent ? this.handleMouseLeave : undefined
          }
          onPointerLeave={
            this.props.usePointerEvent ? this.handleMouseLeave : undefined
          }
          aria-label={formattedAriaLabel}
          role="listbox"
        >
          {showMonthYearPicker ? this.renderMonths() : this.renderQuarters()}
        </div>
      );
    }

    // For regular calendar view, use table structure
    return (
      <div role="table">
        {this.props.dayNamesHeader && (
          <div role="rowgroup">{this.props.dayNamesHeader}</div>

    if (
      this.props.showTimeSelect &&
      (this.state.monthContainer || this.props.showTimeSelectOnly)
    ) {
      return (
        <Time
          {...Calendar.defaultProps}
          {...this.props}
          onChange={this.props.onTimeChange}
          format={this.props.timeFormat}
          intervals={this.props.timeIntervals}
          monthRef={this.state.monthContainer}
        />
      );
    }
    return;
  };

  renderInputTimeSection = (): React.ReactElement | undefined => {
    const time = this.props.selected
      ? new Date(this.props.selected)
      : undefined;
    const timeValid = time && isValid(time) && Boolean(this.props.selected);
    const timeString = timeValid
      ? `${addZero(time.getHours())}:${addZero(time.getMinutes())}`
      : "";
    if (this.props.showTimeInput) {
      return (
        <InputTime
          {...Calendar.defaultProps}
          {...this.props}
          date={time}
          timeString={timeString}
          onChange={this.props.onTimeChange}
        />
      );
    }
    return;
  };

  renderAriaLiveRegion = (): React.ReactElement => {
    // Don't render aria-live message if date is invalid
    if (!isValid(this.state.date)) {
      return (
        <span
          role="alert"
          aria-live="polite"
          className="react-datepicker__aria-live"
        />
      );
    }

    const { startPeriod, endPeriod } = getYearsPeriod(
      this.state.date,
      this.props.yearItemNumber ?? Calendar.defaultProps.yearItemNumber,
    );
    let ariaLiveMessage;

    if (this.props.showYearPicker) {
      ariaLiveMessage = `${startPeriod} - ${endPeriod}`;
    } else if (
      this.props.showMonthYearPicker ||
      this.props.showQuarterYearPicker
    ) {
      ariaLiveMessage = getYear(this.state.date);
    } else {
      ariaLiveMessage = `${getMonthInLocale(
        getMonth(this.state.date),
        this.props.locale,
      )} ${getYear(this.state.date)}`;
    }

    return (
      <span
        role="alert"
        aria-live="polite"
        className="react-datepicker__aria-live"
      >
        {this.state.isRenderAriaLiveMessage && ariaLiveMessage}
      </span>
    );
    );
  };

  renderChildren = (): React.ReactElement | undefined => {
    if (this.props.children) {
      return (
        <div className="react-datepicker__children-container">
          {this.props.children}
        </div>
      );
    }
    return;
  };

  render(): React.ReactElement {
    const Container = this.props.container || CalendarContainer;
    return (
      <ClickOutsideWrapper
        onClickOutside={this.handleClickOutside}
        style={{ display: "contents" }}
        ignoreClass={this.props.outsideClickIgnoreClass}
      >
        <div style={{ display: "contents" }} ref={this.containerRef}>
          <Container
            className={clsx("react-datepicker", this.props.className, {
              "react-datepicker--time-only": this.props.showTimeSelectOnly,
            })}
            showTime={this.props.showTimeSelect || this.props.showTimeInput}
            showTimeSelectOnly={this.props.showTimeSelectOnly}
            inline={this.props.inline}
          >
            {this.renderAriaLiveRegion()}
            {this.renderPreviousButton()}
            {this.renderNextButton()}
            {this.renderMonths()}
            {this.renderYears()}
            {this.renderTodayButton()}
            {this.renderTimeSection()}
            {this.renderInputTimeSection()}
            {this.renderChildren()}
          </Container>
        </div>
      </ClickOutsideWrapper>
    );
  }
}

